 if($a==='test_sms'){$phone=preg_replace('/\D+/','',(string)($_POST['phone']??''))??'';if(!preg_match('/^09\d{9}$/',$phone)){$err=ts_error_text('SMS-501');}else{ts_queue_sms($pdo,null,$phone,'test_'.date('His'),'پیام آزمایشی سوپرمارکت طهران');$r=ts_process_sms_queue($pdo,3);$msg=($r['sent']??0)>0?'پیام تست به سرویس ارسال شد.':ts_error_text(($r['disabled']??false)?'SMS-502':'SMS-503');}}
 if($a==='process_sms'){$r=ts_process_sms_queue($pdo,10);$msg='پردازش صف: ارسال '.(int)$r['sent'].' · ناموفق '.(int)$r['failed'].(($r['disabled']??false)?' · '.ts_error_text('SMS-502'):'');}
 if($a==='save_payment'){set_store_setting($pdo,'payment_enabled',isset($_POST['enabled'])?'1':'0');set_store_setting($pdo,'payment_provider','zarinpal');set_store_setting($pdo,'payment_multiplier',(string)max(1,min(100,(int)($_POST['multiplier']??10))));$m=trim((string)($_POST['merchant_id']??''));if($m!=='')set_store_setting($pdo,'payment_merchant_id',$m);$msg='تنظیمات پرداخت ذخیره شد.';}
